def transform(grid):
    h, w = len(grid), len(grid[0])
    marked_rows = {
        r for r in range(h)
        if all(x == grid[r][0] for x in grid[r])
    }
    marked_cols = {
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    }

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r in marked_rows or c in marked_cols:
                out[r][c] = 2
    return out
